@CircuitBreaker(name = "cbDemo", fallbackMethod = "cbFallback")
String wolajZCircuitBreakerem(int id) {
    if (symulujBlad(id)) throw new RuntimeException("Serwis niedostepny");
    return "OK dla " + id;
}

String cbFallback(int id, Throwable t) {
    return "FALLBACK dla wywolania " + id;
}

@Retry(name = "retryDemo", fallbackMethod = "retryFallback")
String wolajZRetry() { /* moze zawiesc kilka razy, zanim sie uda */ }

@RateLimiter(name = "limiterDemo", fallbackMethod = "rateLimiterFallback")
String wolajZRateLimiterem(int id) { /* ograniczona liczba wywolan na okres */ }

CircuitBreakerRegistry registry = context.getBean(CircuitBreakerRegistry.class);
CircuitBreaker cb = registry.circuitBreaker("cbDemo");

System.out.println("Stan: " + cb.getState());
System.out.println("Nieudane wywolania: " + cb.getMetrics().getNumberOfFailedCalls());

@Service
class OrdersService {
    @CircuitBreaker(name = "cbDemo", fallbackMethod = "cbFallback")
    String wolajZCircuitBreakerem(int id) { /* ... */ }

    void wywolajWiele() {
        this.wolajZCircuitBreakerem(1); // brak proxy - circuit breaker NIE dziala
    }
}

@Service
class OrdersService {
    @CircuitBreaker(name = "cbDemo", fallbackMethod = "cbFallback")
    String wolajZCircuitBreakerem(int id) { /* ... */ }
}

@Service
class OrdersOrchestrator {
    private final OrdersService service;
    void wywolajWiele() {
        service.wolajZCircuitBreakerem(1); // przez proxy - dziala poprawnie
    }
